import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '../../../components/NavigationButtons'
import type { Post } from '../../page'

export interface Comment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

export interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

export const revalidate = 300 // 5 minutes
export const dynamicParams = true

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  try {
    const res = await fetch(
      `https://jsonplaceholder.typicode.com/posts/${id}`,
      { next: { revalidate: 300 } }
    )
    if (!res.ok) {
      return {
        title: 'Post Not Found - My Blog',
      }
    }
    const post: Post = await res.json()
    if (!post || !post.id) {
      return {
        title: 'Post Not Found - My Blog',
      }
    }

    const description = post.body.substring(0, 160)

    return {
      title: `${post.title} - My Blog`,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return {
      title: 'Post Not Found - My Blog',
    }
  }
}

export default async function BlogPost({ params }: BlogPostPageProps) {
  const { id } = await params

  let post: Post
  let comments: Comment[]

  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ])

    if (!postRes.ok) {
      notFound()
    }

    post = await postRes.json()
    comments = await commentsRes.json()

    if (!post || !post.id) {
      notFound()
    }
  } catch {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

import { NextRequest, NextResponse } from 'next/server'

export interface ApiPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

export interface CreatePostRequest {
  title?: string
  content?: string
}

export async function GET(): Promise<NextResponse<ApiPost[]>> {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts, { status: 200 })
}

export async function POST(
  request: NextRequest
): Promise<NextResponse<ApiPost | { error: string }>> {
  const body: CreatePostRequest = await request.json()
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextRequest, NextResponse } from 'next/server'
import type { ApiPost, CreatePostRequest } from '../route'

export interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await params
  const body: CreatePostRequest = await request.json()
  const { title, content } = body

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<{ message: string }>> {
  const { id } = await params

  // Simulate deleting a post
  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

